		s = 0
		for i in range(20):
			o = 10 ** i - 1
			if o > n:
				break
			s += (n - o) * (n - o + 1) // 2
		return s

	def binary_search(k):
		n = 0
		for p in range(63, -1, -1):
			if length(n + 2 ** p) < k:
				n += 2 ** p
		return n

	def sequence(n):
