	letters = list(text)
	for i in range(1, len(letters), 2):
		letters[i] = text[i].swapcase()
	swapped = letters[:]
	for i in range(1, len(letters)):
		letters[i] = region[region.index(swapped[i - 1]) - region.index(swapped[i])]
