	equation = equation.replace('+', ')+')
	equation = equation.replace('-', ')-')
	equation = equation.replace('*', ')*')
	equation = equation.replace('/', ')//')
	equation = equation.replace('%', ')%')
	equation = equation.replace('^', ')**')
	equation = '(' * equation.count(')') + equation
	try:
		return eval(equation)
	except:
		pass

def solve(xs):
	(x, y, z) = sorted(xs)
	return min(x + y, (x + y + z) // 2)

def poly_add(p1, p2):
	if p1 == []:
		return p2
	if p2 == []:
		return p1
	return [p1[0] + p2[0]] + poly_add(p1[1:], p2[1:])
